nnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “lentil”; official portions remain separate."}},{"source_id":"168917","approved_food_id":"norm_foods:quinoa","official_name":"QUINOA","official_portion":"3 oz if eating other complex carbs; 5–6 oz if no other complex carbs","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “quinoa”; official portions remain separate."}},{"source_id":"175122","approved_food_id":"norm_foods:atlantic_or_spanish_mackerel","official_name":"ATLANTIC OR SPANISH MACKEREL","official_portion":"6–8 oz","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “mackerel”; official portions remain separate."}},{"source_id":"170567","approved_food_id":"norm_foods:raw_or_lightly_roasted_nuts_almonds_pistachios_walnuts","official_name":"RAW OR LIGHTLY ROASTED NUTS (ALMONDS, PISTACHIOS, WALNUTS)","official_portion":"1–2 oz","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “almond”; official portions remain separate."}},{"source_id":"171707","approved_food_id":"norm_oils:avocado_or_avocado_oil","official_name":"AVOCADO OR AVOCADO OIL","official_portion":"1–1.5 TBSP Per Day","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “avocado”; official portions remain separate."}},{"source_id":"170593","approved_food_id":"norm_oils:walnut_oil","official_name":"WALNUT OIL","official_portion":"1–1.5 TBSP Per Day","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “walnut”; official portions remain separate."}},{"source_id":"175122","approved_food_id":"norm_oils:fatty_fish_salmon_mackerel_sardines","official_name":"FATTY FISH (SALMON, MACKEREL, SARDINES)","official_portion":"1–1.5 TBSP Per Day","phase_guidance":"Thinnr Metabolic Normalization Phase","constraints":{"reviewRationale":"Reviewed USDA generic variant for “mackerel”; official portions remain separate."}}]$seed_links$::jsonb)
    as x(source_id text, approved_food_id text, official_name text,
         official_portion text, phase_guidance text, constraints jsonb)
)
insert into public.food_catalog_approved_links (
  catalog_id, approved_food_id, official_name, official_portion, phase_guidance,
  constraints, reviewed_at
)
select item.id, seed.approved_food_id, seed.official_name, seed.official_portion,
  seed.phase_guidance, seed.constraints, '2026-09-25T00:00:00.000Z'::timestamptz
from seed join public.food_catalog_items item
  on item.source = 'usda_fdc' and item.source_id = seed.source_id
on conflict (catalog_id, approved_food_id) do update set
  official_name = excluded.official_name, official_portion = excluded.official_portion,
  phase_guidance = excluded.phase_guidance, constraints = excluded.constraints,
  reviewed_at = excluded.reviewed_at;

do $seed_assertions$
begin
  if (select count(*) from public.food_catalog_items
      where source = 'usda_fdc' and provenance->>'release' = '2018-04') < 259 then
    raise exception 'USDA catalog seed did not load all 259 rows';
  end if;
  if (select count(*) from public.food_catalog_approved_links
      where reviewed_at = '2026-09-25T00:00:00.000Z'::timestamptz) < 83 then
    raise exception 'USDA catalog seed did not load all 83 approved links';
  end if;
end $seed_assertions$;
commit;
